### React/TypeScript Source Draft

#### `EventList.tsx`

```tsx
import React from 'react';
import { useQuery } from '@apollo/client';
import gql from 'graphql-tag';

const GET_EVENTS = gql`
  query GetEvents {
    events {
      id
      name
      description
      date
      location
      capacity
      availableSpaces
    }
  }
`;

interface Event {
  id: string;
  name: string;
  description: string;
  date: Date;
  location: string;
  capacity: number;
  availableSpaces: number;
}

const EventList: React.FC = () => {
  const { loading, error, data } = useQuery<{ events: Event[] }>(GET_EVENTS);

  if (loading) return <div>Loading...</div>;
  if (error) return <div>Error: {error.message}</div>;

  return (
    <ul>
      {data.events.map(event => (
        <li key={event.id}>
          <h3>{event.name}</h3>
          <p>{event.description}</p>
          <p>Date: {event.date.toLocaleDateString()}</p>
          <p>Location: {event.location}</p>
          <p>Capacity: {event.capacity}</p>
          <p>Available Spaces: {event.availableSpaces}</p>
        </li>
      ))}
    </ul>
  );
};

export default EventList;
```

#### `CustomerInquiry.tsx`

```tsx
import React, { useState } from 'react';
import { useMutation, gql } from '@apollo/client';

const CREATE_INQUIRY = gql`
  mutation CreateInquiry($customerId: ID!, $eventId: ID!) {
    createInquiry(customerId: $customerId, eventId: $eventId) {
      id
      status
    }
  }
`;

interface Inquiry {
  id: string;
  customerId: string;
  eventId: string;
  status: 'pending' | 'approved' | 'rejected';
}

const CustomerInquiry: React.FC<{ customerId: string; eventId: string }> = ({ customerId, eventId }) => {
  const [createInquiry] = useMutation<CreateInquiryResult>(CREATE_INQUIRY);
  const [status, setStatus] = useState<'pending' | 'approved' | 'rejected'>('pending');

  const handleSubmit = async () => {
    const result = await createInquiry({ variables: { customerId, eventId } });
    if (result.data) {
      setStatus(result.data.createInquiry.status);
    }
  };

  return (
    <div>
      <h3>Submit Inquiry</h3>
      <button onClick={handleSubmit} disabled={status !== 'pending'}>
        Submit
      </button>
      <p>Status: {status}</p>
    </div>
  );
};

interface CreateInquiryResult {
  createInquiry: Inquiry;
}

export default CustomerInquiry;
```

